const ISSUE_OPTIONS = {
  'Academics':   ['Attendance','Certificates','Examination','Letters','Learning Material','Projects','Viva','Others'],
  'Facilities':  ['Carpentry','Electrical','House Keeping','Plumbing','Security','Others'],
  'Finance':     ['Fees','Others'],
  'IT':          ['Admin Portal','Gsuite','Group Creation','ID Card','Internet Connectivity','Learning Platform','Microsoft Office','Online Library Access','Others'],
  'PACE':        ['Admission','Academics','Degree and Certificate','Examination/Result','Fee-related','Grievance','Technical Issues','Transcripts'],
};

const TICKET_TYPE_NOTES = {
  'Attendance Condonation Under AER': '<p><strong>Note:</strong> Your application will be considered at the end of the Trimester only if your attendance in the concerned subject is at least 66%.</p><p>Only One attachment is permitted. Please merge your supporting documents into one document and upload.</p>',
  'OOR Intimation': '<p>No approval required. Ticket will be automatically closed on submission.</p>',
  'Electric Appliance Declaration': '<p>No approval required. Ticket will be automatically closed on submission.</p>',
};

/**
 * Calculate duration between two Frappe Datetime strings 'YYYY-MM-DD HH:MM:SS'.
 * Returns a string like '2h 30m', or '' if inputs are invalid or end <= start.
 */
function calcTripTime(start, end) {
  if (!start || !end) return '';
  var s = new Date(start.replace(' ', 'T'));
  var e = new Date(end.replace(' ', 'T'));
  if (isNaN(s) || isNaN(e) || e <= s) return '';
  var mins = Math.floor((e - s) / 60000);
  return Math.floor(mins / 60) + 'h ' + String(mins % 60).padStart(2, '0') + 'm';
}

async function setupForm({ doc, call, applyFilters, setAbout }) {

  // ── 1. Single API call to get role flags ───────────────────────────────────
  var roleCtx = { is_faculty: false, is_student: false };
  try {
    roleCtx = await call('helpdesk.api.nls_student.get_user_role_context');
  } catch(e) {
    console.error('NLS: get_user_role_context failed', e);
  }

  // ── 2a. FACULTY branch ─────────────────────────────────────────────────────
  if (roleCtx.is_faculty) {

    // Fetch faculty details now (before the setTimeout) so the API call
    // doesn't depend on timing, but assign into doc after a short delay.
    // This is necessary because TicketNew.vue calls setupTemplateFields()
    // synchronously right after setupCustomizations() starts, wiping all
    // doc keys back to ''. Using setTimeout(0) defers our assignments
    // until after that synchronous wipe has completed.
    var tctx = null;
    try {
      tctx = await call('helpdesk.api.nls_student.get_transport_context');
    } catch(e) {
      console.error('NLS: get_transport_context failed', e);
    }

    // Use a small delay to ensure we run after setupTemplateFields wipes doc
    setTimeout(function() {
      doc['ticket_type'] = 'Travel & Transportation';
      if (tctx) {
        doc['custom_transport_requestor']       = tctx['custom_transport_requestor']       || '';
        doc['custom_transport_requestor_email'] = tctx['custom_transport_requestor_email'] || '';
      }
    }, 50);

    // Return only the onChange handlers relevant to faculty
    return {
      onChange: {
        custom_transport_start_time: function(value) {
          doc['custom_transport_trip_time'] =
            calcTripTime(value, doc['custom_transport_end_time'] || '');
        },
        custom_transport_end_time: function(value) {
          doc['custom_transport_trip_time'] =
            calcTripTime(doc['custom_transport_start_time'] || '', value);
        }
      }
    };
  }

  // ── 2b. STUDENT / PACE APPLICANT branch ───────────────────────────────────
  var isStudent = (roleCtx.is_student === true);
  var sctx = null;
  if (isStudent) {
    try {
      sctx = await call('helpdesk.api.nls_student.get_student_context');
    } catch(e) {
      console.error('NLS: get_student_context failed', e);
    }
  }

  // Defer assignment past setupTemplateFields wipe (same reason as faculty branch)
  setTimeout(function() {
    doc['custom_is_student_user'] = isStudent;
    if (isStudent && sctx) {
      var sfields = [
        'custom_student_name', 'custom_student_id', 'custom_programme',
        'custom_current_year', 'custom_current_term',
        'custom_contact_number', 'custom_hostel', 'custom_room_no'
      ];
      sfields.forEach(function(f) { doc[f] = sctx[f] || ''; });
    }
  }, 50);

  // ── 3. Student / other-role onChange handlers ──────────────────────────────
  return {
    onChange: {
      ticket_type: function(value) {
        applyFilters('custom_type_of_issue', ISSUE_OPTIONS[value] || null);
        if (typeof setAbout === 'function') setAbout(TICKET_TYPE_NOTES[value] || '');
      }
    }
  };
}
